def check_valid_move(move, player_set, used_set, n):
    if move in used_set:
        return False
    for chosen_num in player_set:
        if abs(move - chosen_num) == 1:
            return False
    if not (1 <= move <= n):
        return False
    return True

# Test N=4, looking for a loss scenario (Alice blocked)
N = 4
A = []
B = []
Used = set()

# 1. Alice chooses 2
A.append(2)
Used.add(2)

# 2. Bob chooses 4
if check_valid_move(4, B, Used, N):
    B.append(4)
    Used.add(4)
else:
    print("Invalid B move 1")
    exit()

# 3. Alice's turn. Remaining choices: {1, 3}
remaining = set(range(1, N + 1)) - Used
print(f"State before Alice's move 2: A={A}, B={B}, Used={Used}. Remaining={remaining}")

blocked = True
for move in remaining:
    # Check validity for Alice: must not be consecutive to 2
    if check_valid_move(move, A, Used, N):
        blocked = False
        print(f"Alice can move with: {move}")
        break

if blocked:
    print("Alice is blocked! Bob wins.")
else:
    pass

